internal object DuaAsDraft5 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_q_lut_najjini_ahli" to DuaText("লুটৰ দুৱা (এ. এছ.)-মোৰ পৰিয়াল বচাব", "হে মোৰ প্ৰভু, মোক আৰু মোৰ পৰিয়ালক তেওঁলোকে কৰা (পৰিণাম) ৰ পৰা ৰক্ষা কৰা।", "নিজৰ পৰিয়ালক অশুভ পৰিৱেশৰ পৰা ৰক্ষা কৰা।", "পৰিয়ালক দুষ্টতাৰ পৰা সুৰক্ষা দিয়া।"),
        "dua_q_sulaiman_awzini" to DuaText("কৃতজ্ঞতাৰ বাবে চুলাইমানৰ দুৱা (এ. এছ.)", "হে মোৰ প্ৰভু, তুমি মোক আৰু মোৰ পিতৃ-মাতৃক দিয়া অনুগ্রহৰ বাবে মই কৃতজ্ঞ হ'বলৈ আৰু তোমাক সন্তুষ্ট কৰা সৎকৰ্ম কৰিবলৈ আৰু তোমাৰ দয়াৰ দ্বাৰা মোক তোমাৰ সৎকৰ্মশীল দাসসকলৰ মাজত অন্তৰ্ভুক্ত কৰিবলৈ অনুমতি দিয়ক।", "আশীৰ্বাদৰ বাবে কৃতজ্ঞ হোৱাৰ ক্ষমতাৰ বাবে।", "চুলায়মান (এ. এছ.) ৰ কৃতজ্ঞতাৰ দুআ।"),
        "dua_q_musa_zalamtu" to DuaText("মুসাৰ দুআ (আৰু এ. এছ.)-মই নিজকে ভুল কৰিলো", "হে মোৰ প্ৰভু, মই নিজৰ ওপৰত অন্যায় কৰিছোঁ, গতিকে মোক ক্ষমা কৰক।", "ভুল হোৱাৰ পিছত তৎক্ষণাত অনুতাপ কৰা।", "আল্লাহে মূছাক (আৰ. আৰ.) ক্ষমা কৰিছিল।"),
        "dua_q_musa_najjini" to DuaText("মুসাৰ দুআ (আৰু)-মোক নিৰ্যাতনৰ পৰা ৰক্ষা কৰক", "হে মোৰ প্ৰভু, অন্যায়কাৰী লোকসকলৰ পৰা মোক উদ্ধাৰ কৰা।", "যেতিয়া নিৰ্যাতনকাৰীসকলক ভয় কৰে।", "ইজিপ্ত এৰি যোৱাৰ সময়ত মুসা (এ. এছ.) ৰ দুআ।"),
        "dua_q_lut_unsurni" to DuaText("লুটৰ দুৱা (এ. এছ.)-দুৰ্নীতিৰ বিৰুদ্ধে সহায়", "হে মোৰ প্ৰভু, দুৰ্নীতি কৰা লোকসকলৰ বিৰুদ্ধে মোক সহায় কৰক।", "দুৰ্নীতি বিয়পোৱাসকলৰ বিৰুদ্ধে সহায়ৰ বাবে।", "সত্যৰ ওপৰত অটল হৈ থকা লোকসকলৰ দুৱা।"),
        "dua_q_hab_li_salihin" to DuaText("এজন ধাৰ্মিক সন্তানৰ বাবে ইব্ৰাহিমৰ দুআ (এ. এছ.)", "হে মোৰ প্ৰভু, মোক সৎকাৰীসকলৰ মাজৰ পৰা এটা সন্তান প্ৰদান কৰা।", "ধাৰ্মিক সন্তান বিচাৰি।", "ইয়াৰ জৰিয়তে দুআ ইছমাইল (এ. এছ.) প্ৰদান কৰা হৈছিল।"),
        "dua_q_wasita_kulla_shay" to DuaText("সিংহাসন বহন কৰা দূতাসকলৰ দুৱা", "হে আমাৰ প্ৰভু, তুমি সকলো বস্তু দয়া আৰু জ্ঞানৰে আৱৰি ৰাখিছা, সেয়েহে যিসকলে অনুতপ্ত হয় আৰু তোমাৰ পথ অনুসৰণ কৰে তেওঁলোকক ক্ষমা কৰা, আৰু তেওঁলোকক জাহান্নামৰ শাস্তিৰ পৰা ৰক্ষা কৰা।", "সিংহাসন বহন কৰা দূতে বিশ্বাসীসকলৰ বাবে এই দুআটো তৈয়াৰ কৰে।", "দূতাসকলৰ দুআত অন্তৰ্ভুক্ত হোৱাৰ উদ্দেশ্যৰে পাঠ কৰা হৈছিল।"),
        "dua_q_ikhwanina" to DuaText("আমাৰ পূৰ্বৰ ভাতৃসকলৰ বাবে", "হে আমাৰ প্ৰভু, আমাক আৰু আমাৰ ভাতৃসকলক ক্ষমা কৰা, যিসকলে আমাৰ পূৰ্বে বিশ্বাস কৰিছিল। আৰু যিসকলে বিশ্বাস কৰিছিল তেওঁলোকৰ প্ৰতি আমাৰ হৃদয়ত কোনো ক্ষোভ সৃষ্টি নকৰিব। হে আমাৰ প্ৰভু, তুমি নিশ্চয় দয়ালু, দয়াময়।", "পূৰ্বে অহা বিশ্বাসীসকলৰ বাবে আৰু এক পৰিষ্কাৰ হৃদয়ৰ বাবে এটা দুআ।", "সম্ভ্ৰান্ত সঙ্গী (আৰ. এ.) আৰু পূৰ্বৰ বিশ্বাসীসকলৰ বাবে এটা দুআ।"),
        "dua_q_alayka_tawakkalna" to DuaText("তোমাৰ ওপৰত আমি বিশ্বাস কৰোঁ (ইব্ৰাহিম আৰু আৰু আৰু)", "হে আমাৰ প্ৰভু, আমি তোমাৰ ওপৰত নিৰ্ভৰ কৰোঁ, আমি তোমাৰ ফালে ঘূৰি আহিছোঁ আৰু তোমাৰ ফালেই উভতি আহিছোঁ। হে আমাৰ প্ৰভু, আমাক কাৰোবাকৰ বাবে পৰীক্ষা নকৰিবা আৰু আমাক ক্ষমা কৰা। হে আমাৰ প্ৰভু, তুমি নিশ্চয় সৰ্বশক্তিমান, দৰ্শক।", "ইব্ৰাহিম (আৰু তেওঁৰ সঙ্গীসকলৰ দুআ।", "আল্লাহৰ ওপৰত নিৰ্ভৰশীলতা আৰু তেওঁৰ ফালে ঘূৰি অহাৰ এক দ্বৈত।"),
        "dua_q_atmim_nurana" to DuaText("আমাৰ পোহৰ নিখুঁত কৰক", "হে আমাৰ প্ৰভু, আমাৰ বাবে আমাৰ পোহৰ নিখুঁত কৰা আৰু আমাক ক্ষমা কৰা। নিশ্চয় তুমি সকলো বস্তুৰ ওপৰত ক্ষমতাশালী।", "পুনৰুত্থানৰ দিনা বিশ্বাসীসকলৰ দুআ।", "চিৰাটত পোহৰ বিচাৰি।"),
        "dua_q_asiya_baytan" to DuaText("এছিয়াৰ দুৱা-জান্নাহৰ এটা ঘৰ", "হে মোৰ প্ৰভু, তোমাৰ ওচৰত মোৰ বাবে জৰুবত এটা ঘৰ নিৰ্মাণ কৰা, মোক ফৰৌণ আৰু তেওঁৰ কৰ্মৰ পৰা ৰক্ষা কৰা, আৰু মোক অন্যায়কাৰী লোকসকলৰ পৰা ৰক্ষা কৰা।", "ফাৰৌণৰ পত্নী আছিয়াৰ দুআ।", "ঈশ্বৰে তেওঁক বিশ্বাসীসকলৰ বাবে এক উদাহৰণ হিচাপে গঢ়ি তুলিছিল।"),
        "dua_adhan_response" to DuaText("অধানক উত্তৰ দিয়া", "আল্লাহৰ বাহিৰে কোনো শক্তি আৰু শক্তি নাই।", "মুয়েজিনে যি কয় তাক পুনৰাবৃত্তি কৰক;'হায়্যা'আলাস-ছালাহ'আৰু'হায়্যা'আলাল-ফালাহ'ত এইটো কোৱা হয়।", "যিজনে হৃদয়ৰ পৰা উত্তৰ দিব তেওঁ স্বৰ্গত প্ৰৱেশ কৰিব।"),
        "dua_adhan_shahadah" to DuaText("মুয়াজ্জিনৰ শ্বাহাদাহৰ পিছত", "আৰু মইও সাক্ষ্য দিছোঁ যে আল্লাহৰ বাহিৰে কোনোৰে উপাসনা কৰাৰ অধিকাৰ নাই, কেৱল, কোনো অংশীদাৰ অবিহনে, আৰু মহম্মদ ছলীহ আলীহ ৱাছলেম তেওঁৰ দাস আৰু ৰাছুল। মই আল্লাহক প্ৰভু হিচাপে, মহম্মদ ছলীহ ৱাছলক ৰাছুল হিচাপে আৰু ইছলামক ধৰ্ম হিচাপে লৈ সন্তুষ্ট।", "মুয়েজিনৰ বিশ্বাসৰ সাক্ষ্য শুনি।", "তেওঁৰ পাপসমূহ ক্ষমা কৰা হয়।"),
        "dua_istiftah_baid" to DuaText("দুৱা খোলকঃ মোক পাপৰ পৰা দূৰ কৰা", "হে আল্লাহ, তুমি পূবৰ পৰা পশ্চিমলৈ দূৰত্ব বজাই ৰাখি মোৰ পাপৰ পৰা মোক দূৰ কৰা। হে আল্লাহ, মোক পাপৰ পৰা পৰিষ্কাৰ কৰা, যেনেকৈ বগা কাপোৰেৰে লেতেৰা পৰিষ্কাৰ কৰা হয়। হে আল্লাহ, মোৰ পাপবোৰ পানী, বৰফ আৰু শিলাবৃষ্টিৰে ধুই পেলাওক।", "মুকলি তাকবীৰৰ পিছত (সানাৰ ঠাইত কোৱা হ'ব পাৰে)।", "নবী (ছাঃ)-এ তাকবীৰ আৰু আবৃত্তিৰ মাজত এই পাঠ কৰিছিল।"),
        "dua_hamdan_kathiran" to DuaText("ৰুকুৰ পিছত প্ৰচুৰ প্ৰশংসা", "হে আমাৰ প্ৰভু, তোমাৰ প্ৰশংসা-প্ৰচুৰ, বিশুদ্ধ আৰু আশীৰ্বাদপ্ৰাপ্ত প্ৰশংসা।", "ৰুকুৰ পৰা উঠাৰ পিছত,'ৰব্বনা লাকাল-হামদ'ৰ সৈতে।", "ত্ৰিশৰো অধিক দূতে ইয়াক প্ৰথম ৰেকৰ্ড কৰিবলৈ দৌৰি আছিল।"),
        "dua_subbuhun_quddus" to DuaText("সুব্বুহুন কুদ্দুছ (ৰুকু আৰু সুজুদ)", "(আল্লাহ) সৰ্বাধিক মহিমান্বিত, সৰ্বাধিক পবিত্ৰ, দূত আৰু আত্মাৰ প্ৰভু (জিব্ৰিল)।", "ৰুকু আৰু চুজুদত।", "নবী (ছাঃ)-এ ইয়াক ৰুকু আৰু চুজুদত পাঠ কৰিছিল।"),
        "dua_sujood_dhanbi_kullah" to DuaText("সুজুদত-মোৰ সকলো পাপ ক্ষমা কৰক।", "হে আল্লাহ, মোৰ সকলো পাপ-সৰু আৰু ডাঙৰ, প্ৰথম আৰু শেষ, মুকলি আৰু লুকুৱাই ৰখা-মোক ক্ষমা কৰা।", "চুজুদত।", "প্ৰস্ট্রেচন হৈছে এনে এক স্থান য'ত দুআৰ উত্তৰ দিয়া হয়।"),
        "dua_sujood_ridaka" to DuaText("আপোনাৰ আনন্দত আশ্ৰয় লওক", "হে আল্লাহ, মই তোমাৰ ক্ৰোধৰ পৰা তোমাৰ সন্তুষ্টিত আশ্ৰয় বিচাৰোঁ, তোমাৰ শাস্তিৰ পৰা ক্ষমা বিচাৰোঁ, আৰু তোমাৰ পৰা তোমাৰ আশ্ৰয় বিচাৰোঁ। মই তোমাৰ সম্পূৰ্ণ প্ৰশংসা কৰিব নোৱাৰোঁ; তুমি নিজকে প্ৰশংসা কৰাৰ দৰে।", "চুজুদত-আয়েশা (আৰ. এ.)-এ নবী (ছাঃ)-ক এই কথা কোৱা শুনিছিল।", "নবী (ছাঃ)-ৰ এটা চুজুদ দুআ।"),
        "dua_tashahhud" to DuaText("তাশ্বাহুদ (আত-তাহিয়াত)", "সকলো মৌখিক, শাৰীৰিক আৰু বিত্তীয় উপাসনাৰ কাৰ্য্য আল্লাহৰ বাবে। হে নবী, আপোনাৰ ওপৰত শান্তি থাকক, আৰু আল্লাহৰ দয়া আৰু তেওঁৰ আশীৰ্বাদ। আমাৰ ওপৰত আৰু আল্লাহৰ সৎকাৰী বান্দৰসকলৰ ওপৰত শান্তি থাকক। মই সাক্ষ্য দিছোঁ যে আল্লাহৰ বাহিৰে কাৰো উপাসনা কৰাৰ অধিকাৰ নাই, আৰু মই সাক্ষ্য দিছোঁ যে মহম্মদ ছলীহুল্লাহ ছালিম তেওঁৰ বান্দা আৰু ৰাছুল।", "প্ৰতিটো বৈঠকতে-আব্দুল্লাহ ইবন মাছ'উদ (আৰ. এ.) (হানাফি অনুশীলন)-ৰ দ্বাৰা বৰ্ণনা কৰা।", "নবী ছলীহ আলীহ ৱাছলে ইয়াক কোৰাণৰ চুৰাহৰ দৰে শিকোৱাইছিল।"),
        "dua_sajdah_tilawah" to DuaText("পাঠৰ সাজদা", "মোৰ মুখখন তেওঁৰ প্ৰতি সিজদা কৰিছে যিয়ে ইয়াক সৃষ্টি কৰিছিল আৰু তেওঁৰ শক্তি আৰু শক্তিয়েৰে ইয়াৰ শ্ৰৱণ আৰু দৃষ্টিশক্তি কঢ়িয়াই আনিছে।", "আবৃত্তিৰ প্ৰতি সিজদা কৰাৰ সময়ত।", "নৱদূত ছলীহ আলীহ ৱাছলে নিশা প্ৰাৰ্থনাৰ সময়ত এই কথা কৈছিল।"),
        "dua_after_witr" to DuaText("উইটাৰৰ পিছত", "পরম পবিত্ৰ ৰজাৰ গৌৰৱ হওক।", "উইতৰৰ ছালামৰ পিছত তিনিবাৰ, তৃতীয়বাৰ কণ্ঠস্বৰটো ওপৰলৈ তুলি।", "নবী (ছাঃ)-এ এই কথা কোৱাৰ পিছত এই কথা কয়।"),
        "dua_tahajjud_nur" to DuaText("তাহাজ্জুদৰ উদ্বোধনী অনুৰোধ", "হে আল্লাহ, তোমাৰ প্ৰশংসা আছে; তুমি আকাশমণ্ডলী, পৃথিৱী আৰু সেইবোৰৰ ভিতৰৰ সকলোৰে পালনকাৰী। তোমাৰ প্ৰশংসা আছে। তুমি আকাশমণ্ডলী, পৃথিৱী আৰু সেইবোৰৰ ভিতৰৰ সকলোৰে পোহৰ। তোমাৰ প্ৰশংসা আছে; তুমি সত্য, তোমাৰ প্ৰতিশ্ৰুতি সত্য, তোমাৰ সৈতে সাক্ষাৎ সত্য, তোমাৰ বাক্য সত্য, জৰিয়তে সত্য, জাহান্নামে সত্য, নৱগতসকল সত্য, মুহাম্মাদ ছল্লীহ (ছাঃ)-এ সত্য আৰু ঘণ্টা সত্য।", "যেতিয়া নিশাৰ প্ৰাৰ্থনা (তাহাজ্জুদ) (দুআৰ আৰম্ভণিৰ অংশ) আৰম্ভ হয়।", "নবী ছলীহ আলীহ ৱাছলে তাহাজ্জুদৰ বাবে উঠি এই পাঠ কৰিছিল (সম্পূৰ্ণ দুআ আল-বুখাৰীত আছে)।"),
        "dua_rabba_jibrail" to DuaText("বিতৰ্কিত বিষয়সমূহত মোক পথ দেখুৱাওক", "হে আল্লাহ, জিবৰিল, মিকাইল আৰু ইস্ৰাফিলৰ প্ৰভু, আকাশমণ্ডলী আৰু পৃথিৱীৰ সৃষ্টিকৰ্তা, অদৃশ্য আৰু দৃশ্যমানৰ বিষয়ে অৱগত! আপুনি আপোনাৰ দাসসকলৰ মাজত যি মতানৈক্য আছিল তাৰ ওপৰত বিচাৰ কৰিব। আপোনাৰ অনুমতিৰে মোক সত্যৰ ফালে লৈ যাওক যাৰ ওপৰত মতভেদ আছে। নিশ্চিতভাৱে, আপুনি যাক বিচাৰে তেওঁক আপুনি এক পোনপথলৈ লৈ যাব।", "তাহাজ্জুদৰ আৰম্ভণিতে-মতানৈক্যৰ মাজত সত্যৰ দিশ নিৰ্দেশনাৰ বাবে।", "নবী (ছাঃ)-এ এই দুআৰে তেওঁৰ নিশাৰ প্ৰাৰ্থনা আৰম্ভ কৰিছিল।"),
        "dua_going_to_mosque_nur" to DuaText("মছজিদলৈ যোৱা (পোহৰৰ দুৱা)", "হে আল্লাহ, মোৰ হৃদয়ত পোহৰ, মোৰ চকুত পোহৰ, মোৰ কাণত পোহৰ, মোৰ সোঁফালে পোহৰ, মোৰ বাওঁফালে পোহৰ, মোৰ ওপৰত পোহৰ, মোৰ তলত পোহৰ, মোৰ সন্মুখত পোহৰ, মোৰ পিছফালে পোহৰ, আৰু মোৰ বাবে পোহৰ বনাওক।", "ফজ্ৰলৈ মছজিদলৈ যোৱাৰ সময়ত।", "প্ৰবক্তা ছলীহুল্লাহ আলীহ ৱাছলে নামাযৰ বাবে ওলাই যোৱাৰ সময়ত এই পাঠ কৰিছিল।"),
        "dua_waswasa_salah" to DuaText("ছালাহৰ সময়ত ৱাশ্বাসা (খিঞ্জাব)", "মই শাপিত শয়তানৰ পৰা আল্লাহৰ আশ্ৰয় বিচাৰো।", "যেতিয়া প্ৰাৰ্থনাৰ সময়ত শয়তানৰ ফিসফিস কৰা হয়, তেতিয়া আশ্ৰয় লওক আৰু তিনিবাৰ বাওঁফালে পাতলকৈ থুকক।", "উথমান ইবন আবিল -'আছ (আৰ. এ.)-এ এইটো কৰিছিল আৰু ফিসফিস কৰা শব্দবোৰ আঁতৰি গৈছিল।"),
        "dua_alimal_ghayb" to DuaText("অদৃশ্যৰ বিষয়ে জ্ঞাত", "হে আল্লাহ, যি অদৃশ্য আৰু দৃশ্যমানৰ বিষয়ে জানে, আকাশমণ্ডলী আৰু পৃথিৱীৰ সৃষ্টিকৰ্তা, সকলো বস্তুৰ প্ৰভু আৰু ৰজা! মই সাক্ষ্য দিছোঁ যে তোমাৰ বাহিৰে কোনো উপাস্য নাই। মই মোৰ নিজৰ দুষ্টতাৰ পৰা, শায়তান আৰু তেওঁৰ দুষ্টতাৰ পৰা তোমাৰ ওচৰত আশ্ৰয় বিচাৰো।", "ৰাতিপুৱা, সন্ধিয়া আৰু শুৱাৰ আগতে-নবী ছলীহ আলীহ ৱাছলে ইয়াক আবু বক্ৰ (ৰা.) ক শিকাইছিল।", "নিজৰ আৰু শায়তনৰ দুষ্টতাৰ পৰা সুৰক্ষা।"),
        "dua_fitratil_islam" to DuaText("ইছলামৰ ফিত্ৰাৰ ওপৰত", "আমি ইছলামৰ ফিত্ৰাৰ দিনা ৰাতিপুৱা প্ৰৱেশ কৰিছো, আন্তৰিকতাৰ শব্দৰ ওপৰত, আমাৰ নবী মহম্মদ ছলীহ আলীহ ৱাছলামৰ ধৰ্মৰ ওপৰত আৰু আমাৰ পিতৃ ইব্ৰাহিম (আৰু) ৰ পথত, যি সৎ আৰু মুছলমান আছিল, আৰু মুশৰীকসকলৰ ভিতৰত নাছিল।", "ৰাতিপুৱা।", "প্ৰতিদিনে ৰাতিপুৱা নিজৰ বিশ্বাস পুনৰুদ্ধাৰ কৰা।"),
        "dua_amsayna_fitrah" to DuaText("ইছলামৰ ফিত্ৰাৰ দিনা সন্ধিয়া", "আমি ইছলামৰ ফিত্ৰাত সন্ধিয়া প্ৰৱেশ কৰিছো, আন্তৰিকতাৰ শব্দৰ ওপৰত, আমাৰ নবী মহম্মদ ছলীহ আলীহ ৱাছলামৰ ধৰ্মৰ ওপৰত আৰু আমাৰ পিতৃ ইব্ৰাহিম (আৰু) ৰ পথত, যি সৎ আৰু মুছলমান আছিল, আৰু মুশৰীকসকলৰ ভিতৰত নাছিল।", "সন্ধিয়া।", "প্ৰতিদিনে সন্ধিয়া নিজৰ বিশ্বাসৰ নৱীকৰণ কৰক।"),
        "dua_tahleel_10_fajr" to DuaText("ফজ্ৰ আৰু মাগৰিবৰ পিছত দহ তাহলীল", "কেৱল আল্লাহৰ বাহিৰে কাৰো উপাসনা কৰাৰ অধিকাৰ নাই, কেৱল তেওঁৰ, কোনো অংশীদাৰ নাই। তেওঁৰে শাসন আৰু তেওঁৰেই প্রশংসা; তেওঁ জীৱন দিয়ে আৰু মৃত্যু ঘটায়, আৰু তেওঁ সকলো বস্তুৰ ওপৰত ক্ষমতাশালী।", "ফজ্ৰ (আৰু মাঘৰিব) ৰ পিছত দহবাৰ, আপোনাৰ বহা বা কথা কোৱাৰ পৰা আঁতৰি যোৱাৰ আগতে।", "দহটা ভাল কাম, দহটা পাপ মচি পেলোৱা হৈছিল, দহটা পদৰ উচ্চতা বৃদ্ধি কৰা হৈছিল আৰু গোটেই দিনটো শায়তানৰ পৰা সুৰক্ষা দিয়া হৈছিল।"),
        "dua_la_hawla_kanz" to DuaText("এ ট্ৰেজাৰ অৱ জান্না", "আল্লাহৰ বাহিৰে কোনো শক্তি আৰু শক্তি নাই।", "প্ৰায়ে, সকলো সময়তে।", "ই স্বৰ্গৰ অন্যতম সম্পদ।"),
        "dua_four_beloved_words" to DuaText("চাৰিটা আটাইতকৈ প্ৰিয় শব্দ", "গৌৰৱ আল্লাহৰ, সকলো প্ৰশংসা আল্লাহৰ বাবে, আল্লাহৰ বাহিৰে আন কাৰো পূজা কৰাৰ অধিকাৰ নাই, আৰু আল্লাহ সৰ্বশ্ৰেষ্ঠ।", "আল্লাহৰ বাবে আটাইতকৈ প্ৰিয় শব্দ।", "সূৰ্য্য উদয় হোৱা সকলো বস্তুতে পৰা তেওঁলোক নবী (ছাঃ)-ৰ বাবে অধিক মৰমৰ।"),
        "dua_two_light_words" to DuaText("জিভাত দুটা শব্দ পোহৰ হয়", "গৌৰৱ আল্লাহৰ আৰু সকলো প্ৰশংসা তেওঁৰ; গৌৰৱ মহান আল্লাহৰ।", "জিভাত পাতল, স্কেলত গধুৰ।", "অতি দয়ালুৰ প্ৰিয়, জিভাত পাতল আৰু স্কেলত গধুৰ। (আল-বুখাৰীৰ শেষ হাদীছ)"),
        "dua_ya_dhal_jalal" to DuaText("ইয়া ধল-জলালী ৱাল-ইকৰাম", "হে মহামান্য আৰু সন্মানৰ অধিকাৰী!", "ইয়াক দুআত ধৰি ৰাখক-নবীৰ ছলীহ আলীহ ৱাছেলম নিৰ্দেশ।", "নবী (ছাঃ)-এ কৈছিলঃ'ইয়া ধল-জলালী ৱাল-ইক্ৰাম \"ধৰি ৰাখক।"),
        "dua_sleep_wadatu_janbi" to DuaText("তোমাৰ নামত মই শুয়ে পৰিছোঁ।", "হে মোৰ প্ৰভু, মই তোমাৰ নামত মোৰ পক্ষ ৰাখিছোঁ আৰু তোমাৰ নামত মই উঠি আহিছোঁ। যদি তুমি মোৰ আত্মাটো লোৱা, তেন্তে তাৰ ওপৰত দয়া কৰা, আৰু যদি তুমি ইয়াক মুকলি কৰা, তেন্তে ইয়াক সুৰক্ষিত কৰা যেনেকৈ তুমি তোমাৰ ধাৰ্মিক দাসসকলক সুৰক্ষা দিয়া।", "বিচনাটো ধূলি মাৰি শুৱাৰ পিছত।", "শুৱাৰ আগতে নিজৰ আত্মা আল্লাহৰ হাতত অর্পণ কৰা।"),
        "dua_sleep_khalaqta_nafsi" to DuaText("তুমি মোৰ আত্মা সৃষ্টি কৰিলা", "হে আল্লাহ, তুমি মোৰ আত্মা সৃষ্টি কৰিলা আৰু তুমি ইয়াক গ্ৰহণ কৰিবা। ইয়াৰ মৃত্যু আৰু ইয়াৰ জীৱন তোমাৰ। যদি তুমি ইয়াক জীয়াই ৰাখ, ইয়াক ৰক্ষা কৰা, আৰু যদি তুমি ইয়াক মৰাই দিয়া, ইয়াক ক্ষমা কৰা। হে আল্লাহ, মই তোমাৰ কল্যাণ বিচাৰো।", "শুৱাৰ আগতে-ইবন উমৰ (আৰ. এ.)-ৰ দ্বাৰা বৰ্ণনা কৰা।", "নবী (ছাঃ)-এ শুৱাৰ সময়ত এই কথা কোৱাৰ নিৰ্দেশ দিছিল।"),
        "dua_sleep_atamana" to DuaText("শুৱাৰ আগতে কৃতজ্ঞতা", "সকলো প্ৰশংসা সেই আল্লাহৰ বাবে যি আমাক খুৱাইছিল, পানী দিছিল, আমাক যথেষ্ট পৰিমাণে সহায় কৰিছিল আৰু আমাক আশ্ৰয় দিছিল। কিমানজন আছে যাৰ ওচৰত পৰ্যাপ্ত পৰিমাণৰ বা আশ্ৰয় দিবলৈ কোনো নাই।", "যেতিয়া শুবলৈ যায়।", "নবী (ছাঃ)-এ বিছানাত যোৱাৰ সময়ত এই কথা কৈছিল।"),
        "dua_sleep_rabbas_samawat" to DuaText("স্বৰ্গৰ প্ৰভু-আমাৰ ঋণ পৰিশোধ কৰক", "হে আল্লাহ, আকাশমণ্ডলী, পৃথিৱী আৰু শক্তিশালী সিংহাসনৰ প্ৰভু, আমাৰ প্ৰভু আৰু সকলো বস্তুৰ প্ৰভু, বীজ আৰু খেজুৰ-শিলৰ বিভাজনকাৰী, টোৰা, ইনজিল আৰু ফুৰকানৰ প্ৰকাশকাৰী! মই তোমাৰ ওচৰত আশ্ৰয় বিচাৰো সকলো বস্তুৰ দুষ্টতাৰ পৰা যাৰ আগৰ ফালে তুমি ধৰি আছা। হে আল্লাহ, তুমি প্ৰথম, তোমাৰ আগতে একো নাই; তুমি শেষ, তোমাৰ পিছত একো নাই; তুমি প্ৰকাশ, তোমাৰ ওপৰত একো নাই, তুমি লুকুৱাই ৰখা, তোমাৰ পৰা কোনো লুকুৱাই নাই। আমাৰ বাবে আমাৰ ঋণ নিষ্পত্তি কৰা আৰু আমাক দৰিদ্ৰতাৰ পৰা মুক্ত কৰা।", "শুৱাৰ আগতে সোঁফালে শুৱক-ফাতিমাক (আৰ. এ.) শিকোৱা।", "ঋণ আৰু কষ্টৰ পৰা মুক্তিৰ বাবে এটা দুআ।"),
        "dua_sleep_fear" to DuaText("টোপনিৰ ভয় বা অস্বস্তি", "মই তেওঁৰ খং আৰু শাস্তিৰ পৰা, তেওঁৰ দাসসকলৰ দুষ্টতাৰ পৰা, শয়তানৰ ফিসফিস কৰাৰ পৰা আৰু তেওঁলোকৰ মোৰ ওচৰলৈ অহাৰ পৰা আল্লাহৰ নিখুঁত শব্দৰ আশ্ৰয় বিচাৰোঁ।", "যেতিয়া টোপনিৰ সময়ত ভয় বা অস্বস্তি অনুভৱ কৰে।", "এনে কৰিলে, সেই বস্তুটোৱে তেওঁৰ কোনো ক্ষতি নকৰে।"),
        "dua_waking_afani" to DuaText("জেগে উঠাঃ তেওঁ মোৰ আত্মা পুনৰুদ্ধাৰ কৰিছিল", "সকলো প্ৰশংসা মোৰ শৰীৰক সুস্থ কৰি তোলা, মোৰ আত্মা মোক ঘূৰাই দিয়া আৰু মোক তেওঁক স্মৰণ কৰিবলৈ অনুমতি দিয়া আল্লাহৰ বাবে।", "জাগি উঠাৰ সময়ত।", "নতুন ৰাতিপুৱাৰ বাবে কৃতজ্ঞতা।"),
        "dua_allahu_rabbi" to DuaText("হে আল্লাহ, হে মোৰ প্ৰভু।", "হে আল্লাহ, মোৰ প্ৰভু; মই তেওঁৰ লগত কোনো বস্তুৰ সাৰাংশ নকৰোঁ।", "দুখ বা দুখত-নবী ছল্লীহ আলীহ ৱাছলেমে আছমা বিনতে উমাইছ (ৰা.) ক এই শিক্ষা দিছিল।", "কষ্টৰ সময়ত তাৱহিদ ধৰি ৰাখক।"),
    )
}
